import { after } from 'next/server'
import { logPageView } from '@/lib/analytics'

export default function Home() {
  // Schedule analytics logging to run after the response has been sent,
  // so it never delays rendering for the user.
  after(async () => {
    await logPageView({
      path: '/',
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting! We&apos;re glad you&apos;re here.</p>
    </main>
  )
}

